0:
listen              1935;
max_connections     1000;
http_api {
  enabled           on;
  listen            1985;
}
http_server {
  enabled           on;
  listen            8080;
  dir               ./objs/nginx/html;
}
rtc_server {
  enabled           on;
  listen            8000;
  candidate         $CANDIDATE;
}
vhost __defaultVhost__ {
  rtc {
    enabled         on;
    rtmp_to_rtc     on;
    rtc_to_rtmp     off;
  }
  forward {
    enabled         on;
    destination     peertube.default.svc.cluster.local:1935;
  }
}
